CREATE TABLE IF NOT EXISTS vocabularies (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    chapter INTEGER NOT NULL,
    kanji TEXT,
    kana TEXT,
    part_of_speech TEXT CHECK(part_of_speech IN ('noun', 'verb1', 'verb2', 'verb3', 'iAdj', 'naAdji', 'speaking', 'suffix')),
    meaning TEXT,
    note DEFAULT "",
    example DEFAULT "",
    sameVocabId DEFAULT "[]"
    
);









-- Basic Kanji 320 (JLPT N5 & N4) SQL Dump
-- Source: MLC Meguro Language Center Basic Kanji 320

CREATE TABLE IF NOT EXISTS kanjis (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kanji_number INTEGER NOT NULL,
    kanji TEXT NOT NULL,
    level TEXT CHECK(level IN ('N5', 'N4')),
    kunyomi TEXT,
    onyomi TEXT,
    meaning TEXT,
    examples TEXT,
    vocabsId DEFAULT "[]"

);

