INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (1, '人', 'N5', 'ひと', 'ジン、ニン', 'person', '人 ひと person: ここは人が多おおいですね。 | カナダ人 カナダじん Canadian: その人はカナダ人です。 | 三さん人 さんにん three people: こどもが三さ ん人います。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (2, '日', 'N5', 'ひ、か', 'ニチ', 'that day', 'その日 そのひ that day: すみません。その日は いそが忙しいです。 | 三みっ日 みっか the third day of the month: 今日 日 き ょ うは三みっ日です。 | じゅう十五ご 日 じゅうごにち the fifteenth day of the month: 明日 あ し たは十五 じ ゅ う ご日です。 | 日曜よ う日 にちようび Sunday: 日曜よ う日は休やすみです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (3, '一', 'N5', 'ひと（つ）', 'イチ、イッ', 'one', '一つ ひとつ one: すみません。それを一つください。 | 一人り ひとり one person: 一人でホンコンに行い きます。 | 一日 いちにち one day: ホンコンに一日います。 | 一つい日たち ついたち the first day of the month: 一日にホンコンに行い きます。 | 一分ぷん いっぷん one minute: ここからホテルまで一分ぷんです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (4, '二', 'N5', 'ふた（つ）', 'ニ', 'two', '二つ ふたつ two: コーヒーを二つください。 | 二ふつ日 ふつか two days: パリに二日いました。 the second day of the month： 今日 き ょ うは二日です。 | 二人り ふたり two people: 二人で行い きます。 | 二時じ 間かん にじかん two hours: 二時じ 間かんテニスをしました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (5, '三', 'N5', 'みっ（つ）', 'サン', 'three', '三つ みっつ three: ハンバーガーを三つとポテトを二つください。 | 三日 みっか three days: ローマに三日いました。 the third day of the month： 三日にロンドンに行い きます。 | 三人 さんにん three people: 家か 族ぞ くは三人です。 3 人日');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (6, '四', 'N5', 'よっ（つ）、よん、よ', 'シ', 'four', '四つ よっつ four: このパンを四つください。 | 四日 よっか four days: カナダに四日います。 the fourth day of the month： 今日 き ょ うは四日です。 | 四回かい よんかい four times: ディズニーランドに四回かい行い きました。 | 四人 よにん four people: 家か 族ぞ くは四人です。 | 四月がつ しがつ April: 今日 き ょ うは四月がつ四日です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (7, '五', 'N5', 'いつ（つ）', 'ゴ', 'five', '五つ いつつ five: チーズバーガーを五つください。 | 五日 いつか five days: サンフランシスコに五日いました。 the fifth day of the month： 今日 き ょ うは五日です。 | 五人 ごにん five people: 五人でキャンプに行い きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (8, '六', 'N5', 'むっ（つ）', 'ロク', 'six', '六つ むっつ six: ビールを六つください。 | 六むい日 むいか six days: インドに六日いました。 the sixth day of the month： 今日 き ょ うは六日です。 | 六人 ろくにん six people: 家か 族ぞ くは六人です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (9, '七', 'N5', 'なな（つ）、なな', 'シチ', 'seven', '七つ ななつ seven: コーラを七つください。 | 七回かい ななかい seven times: ディズニーシーに七回かい行い きました。 | 七なの日 なのか seven days: ロンドンに七日いました。 the seventh day of the month： 七日は休やすみです。 | 七人 しちにん seven people: 家か 族ぞ くは七人です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (10, '八', 'N5', 'やっ（つ）', 'ハチ', 'eight', '八つ やっつ eight: このりんごを八つください。 | 八よ う日 ようか eight days: シンガポールに八日いました。 the eighth day of the month： 八日は休やすみです。 | 八人 はちにん eight people: 家か 族ぞ くは八人います。 4');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (11, '九', 'N5', 'ここの（つ）', 'キュウ、ク', 'nine', '九つ ここのつ nine: コーヒーを九つください。 | 九日 ここのか nine days: イタリアに九日いました。 the ninth day of the month： 九日は休やすみです。 | 九人 きゅうにん nine people: 家か 族ぞ くは九人です。 | 九月がつ くがつ September: 今日 １ き ょ うは九月がつ九日です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (12, '十', 'N5', 'とお', 'ジュウ', 'ten', '十 とお ten: 「いくつありますか」、「一つ、二つ、・・・・、九つ、十」 | 十日 とおか ten days: オーストラリアに十日いました。 the tenth day of the month： 十日は休やすみです。 | 十人 じゅうにん ten people: 家か 族ぞ くは十人です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (13, '月', 'N5', 'つき', 'ゲツ、ガツ', 'moon', '月 つき moon: 月がとてもきれいです。 month： 月に一回かいサッカーをします。 | 月曜よ う日 げつようび Monday: 月曜よ う日にカナダに行い きます。 | 一か月 いっかげつ one month: ドイツに一か月いました。 | 四月 しがつ April: 四月四日に東と うきょう京に来き ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (14, '火', 'N5', 'ひ', 'カ', 'fire', '火 ひ fire: 火はあぶないです。 | 火曜よ う日 かようび Tuesday: 火曜よ う日にどこに行い きましたか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (15, '水', 'N5', 'みず', 'スイ', 'water', '水 みず water: すみません。水をください。 | 水曜よ う日 すいようび Wednesday: 十三日は水曜よ う日です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (16, '木', 'N5', 'き', 'モク', 'tree', '木 き tree: 木の上う えにカラス(crow)がたくさんいます。 wood： この木のテーブルはいくらですか。 | 木曜よ う日 もくようび Thursday: 二十四日は木曜よ う日です。 月 日 木 日 5');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (17, '金', 'N5', 'かね', 'キン', 'money', 'お金 おかね money: すみません。お金を貸か してください。 | 金 きん gold: これは金のネックレスです。 | 金曜よ う日 きんようび Friday: レッスンは火曜よ う日と金曜よ う日です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (18, '土', 'N5', 'つち', 'ド', 'soil; earth', '土 つち soil; earth: この土はかたいです。 | 土曜よ う日 どようび Saturday: 土曜よ う日にテニスをします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (19, '百', 'N5', '', 'ヒャク', 'hundred', '百円えん ひゃくえん one hundred yen: 百円えんショップはどこにありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (20, '千', 'N5', '', 'セン', 'thousand', '千円えん せんえん one thousand yen: あのレストランのランチは千円えんです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (21, '万', 'N5', '', 'マン', 'ten thousand', '三万円えん さんまんえん thirty thousand yen: このバッグは三万円えんでした。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (22, '円', 'N5', '', 'エン', 'yen', '百円 ひゃくえん one hundred yen: これは三つで百円です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (23, '行', 'N5', 'い（きます）、おこな（います）', 'コウ', 'go', '行きます いきます go: いっしょにレストランに行きませんか。 | 行います おこないます do; hold: どこでミーティングを行いますか。 | 銀ぎん行 ぎんこう bank: これから銀ぎん行に行きます。 | 旅り ょ行します りょこうします travel: ヨーロッパを旅り ょ行したいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (24, '来', 'N5', 'き（ます）', 'ライ', 'come', '来ます きます come: 六月六日にアメリカから東と うきょう京に来ました。 | 来月 らいげつ next month: 来月、一人でカナダに行きます。 行 日');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (25, '休', 'N5', 'やす（みます）', '', 'rest', '休みます やすみます rest: 少す こし休みましょう。 have a day off： 三日から七日まで休みます。 be absent： 明日 休 あ し たのレッスンは休みます。 | 休み やすみ holiday; vacation: 休みにオーストラリアに行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (26, '見', 'N5', 'み（ます）、み（えます）、み（せます）', 'ケン', 'see', '見ます みます see: 富ふ 士じ 山さんを見ました。 look： これを見てください。 watch： テレビでそのニュースを見ました。 | 見えます みえます be visible: ここから東と うきょう京タワーが見えます。 | 見せます みせます show: メニューを見せてください。 | 意い 見 いけん opinion: みなさんの意い 見を聞き きたいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (27, '今', 'N5', 'いま', 'コン', 'now', '今 いま now: 今、ビデオを見ています。 | 今月 こんげつ this month: 今月の十日に東と うきょう京に来ました。 | 今日 き ょ う きょう today: 今日のレッスンはおもしろかったです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (28, '大', 'N5', 'おお（きい）', 'ダイ、タイ', 'big', '大きい おおきい big: 大きい木があります。 | 大学が く だいがく university: イギリスの大学が くに行きたいです。 | 大切せつ たいせつ important: これは大切せつなデータです。 | 大人 大 日 お と な おとな adult: 大人は千八百円です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (29, '小', 'N5', 'ちい（さい）、こ', 'ショウ', 'small', '小さい ちいさい small: あの小さいカップは五百円です。 | 小鳥と り ことり small bird: 木の上に小鳥と りがいます。 | 小学がっ校こ う しょうがっこう elementary school: あれは小学がっ校こ うです。 7');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (30, '上', 'N5', 'うえ、あ（げます）、あ（がります）', 'ジョウ', 'on', '上 うえ on: テーブルの上にお金があります。 above： 窓ま どの上に時と 計けいがあります。 | 上げます あげます raise: 来月からきゅう給りょう料（salary）を上げます。 | 上がります あがります go up; rise: 来月からきゅう給りょう料が上がります。 | 上手ず じょうず good at; skillful: あの人はゴルフが上手ず です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (31, '下', 'N5', 'した、さ（げます）、さ（がります）', 'カ', 'under', '下 した under: テーブルの下にねこがいます。 | くつ下 くつした socks: そのくつ下を見せてください。 | 下げます さげます lower; get down: 来月からきゅう給りょう料を下げます。 | 下がります さがります go down: 来月からきゅう給りょう料が下がります。 | 地ち 下鉄てつ ちかてつ subway; underground: 地ち 下鉄てつで行きましょう。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (32, '中', 'N5', 'なか', 'チュウ', 'inside', '中 なか inside: ポケットの中に五万円あります。 | 中国ご く ちゅうごく China: 中国ご くに行きたいです。 | 電でん話わ 中 でんわちゅう on the phone: 今、電でん話わ 中です。 | 一日中 いちにちじゅう all day long: 休みの日は一日中テレビを見ています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (33, '右', 'N5', 'みぎ', '', 'right', '右 みぎ right: 右にまがってください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (34, '左', 'N5', 'ひだり', '', 'left', '左 ひだり left: 左にまがってください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (35, '山', 'N5', 'やま', 'サン', 'mountain', '山 やま mountain: 今月の休みに山に行きます。 | 富ふ 士じ 山 ふじさん Mt. Fuji: 来月、富ふ 士じ 山に行きます。 hand 2 mouth 日 山 8');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (36, '川', 'N5', 'かわ', '', 'river', '川 かわ river: きれいな川ですね。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (37, '白', 'N5', 'しろ（い）、しろ', '', 'white', '白い しろい white (adj.): 白いコートは三万四千円です。 | 白 しろ white (noun): わたし私は白が好す きです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (38, '本', 'N5', '', 'ホン', 'book; counter for long object; origin; main', '本 ほん book: この本は千二百円です。 | 九本 きゅうほん nine pieces (long object): たばこを九本すいました。 | 日に 本 にほん Japan: 六月にイタリアから日本に来ました。 | 本当と う ほんとう true; real: それは本当と うですか。 | 本社し ゃ ほんしゃ head office: 本社し ゃはどこにありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (39, '子', 'N5', 'こ', '', 'child', '子ども こども child: 中なか川がわさんは六歳さ いの子どもが一人います。 | 子どもたち こどもたち children: 子どもたちは川に行きました。 | この子 このこ this child: この子は四歳さ いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (40, '男', 'N5', 'おとこ', 'ダン', 'man', '男 おとこ man: あの男の人は大おお木き さんです。 | 男の子 おとこのこ boy: 三歳さ いの男の子が一人います。 | 男性せい だんせい man; male: 男性せいのトイレは右です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (41, '女', 'N5', 'おんな', 'ジョ', 'woman', '女 おんな woman: あの女の人はフランス人です。 | 女の子 おんなのこ girl: 五歳さ いの女の子が一人います。 | 女性せい じょせい woman; female: 女性せいのトイレは左です。 子 rice field 男 arm power 女 9 力 日 川');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (42, '父', 'N5', 'ちち', 'フ', '(my) father', '父 ちち (my) father: 父はフランスにいます。 | お父と うさん おとうさん (someone’s) father: お父さんはいつ日本に来ましたか。 | 祖そ 父 そふ (my) grandfather: 祖そ 父は九十五歳さ いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (43, '母', 'N5', 'はは', 'ボ', '(my) mother', '母 はは (my) mother: 母の誕たんじょう生日にプレゼントをあげました。 | お母かあさん おかあさん (someone’s) mother: お母さんはいつ日本に来ますか。 | 祖そ 母 そぼ (my) grandmother: 祖そ 母はやさしいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (44, '友', 'N5', 'とも', '', 'friend', '友だち ともだち friend: 今日、友だちにメールしました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (45, '先', 'N5', 'さき', 'セン', 'earlier', '先に さきに earlier: お先に失し つ礼れいします。 | 先月 せんげつ last month: 先月、友だちとミュージカルを見ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (46, '生', 'N5', 'い（きます）、う（まれます）, なま', 'セイ、ショウ', 'live', '生きます いきます live: 百歳さ いまで生きたいです。 | 生まれます うまれます be born: 先月、子どもが生まれました。 | 生 なま raw: 生の魚さかながきらいです。 | 生ビール なまビール draft beer: すみません。生ビールを一つおねがいします。 | 先生 せんせい teacher: あの女の先生はとてもやさしいです。 | 誕たん生日 たんじょうび birthday: わたし私の誕たん生日は九月六日です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (47, '学', 'N5', 'まな（びます）', 'ガク', 'learn; study', '学びます まなびます learn; study: どこでフランス語を学びましたか。 | 学生 がくせい student: わたしは学生ですから、あまりお金がありません。 | 小学生 しょうがくせい elementary school children: この子は小学生です。 | 中学生 ちゅうがくせい junior high school student: 中学生の子どもが一人います。 | 大学 だいがく university; college: スペインの大学に行きました。 | 大学生 だいがくせい university student: 大学生はよくアルバイトをします。 . . 母 友 two hands 学 roof child');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (48, '校', 'N5', '', 'コウ', 'school', '学校 がっこう school: この学校は新あたらしいです。 | 小学校 しょうがっこう elementary school: うちの近ちかくに小学校があります。 | 中学校 ちゅうがっこう junior high school: あの人は中学校の先生です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (49, '何', 'N5', 'なに、なん', '', 'what', '何 なに what: 休みの日に何をしますか。 | 何 なん ｗhat: これは何ですか。 | 何+\[noun\] なに+\[noun\] what: あの人は何人じんですか。 | 何+\[counter\] なん+\[counter\] how many…: パーティーに何人にん来ましたか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (50, '時', 'N5', 'とき', 'ジ', 'when', '時 とき when: 子どもの時、あまりテレビを見ませんでした。 time： その時、私わたしは十五歳さ いでした。 | 時々 ときどき sometimes: 時々コンビニで水をかいます。 | 一時 いちじ one o’clock: 一時に学校に来てください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (51, '間', 'N5', 'あいだ, ま', 'カン', 'between', '間 あいだ between: マックとスタバの間にケンタッキーがあります。 | 昼ひる間 ひるま daytime: 明日の昼ひる間は いそが忙しいです。 | 時間 じかん time: 今日は時間がありません。 | 二時間 にじかん two hours: 時々二時間ぐらいテニスをします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (52, '分', 'N5', 'わ（けます）', 'フン、ブン', 'divide, share', '分けます わけます divide, share: このケーキをみんなで分けましょう。 | 五分 ごふん five minutes: すみません。五分待ま ってください。 | 十分 じゅっぷん ten minutes: うちから学校まで十分です。 | 十分 じゅうぶん enough; sufficient: もう十分です。ごちそうさまでした。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (53, '半', 'N5', '', 'ハン', 'half', '八時半 はちじはん half past eight: 八時半に学校に行きます。 | 半分 はんぶん half: このパンは大きいですから、半分食た べてください。 （々＝repeat の marker） gate 間 sun spilt 刀 sword 分');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (54, '毎', 'N5', '', 'マイ', 'every', '毎日 まいにち every day: 毎日三十分ジョギングします。 | 毎月 まいつき every month: 毎月二十五日にパーティーをします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (55, '年', 'N5', 'とし', 'ネン', 'year', '年 とし year: その年はとても暑あつかったです。 age： （お）年はいくつですか。 | 今こ 年 ことし this year: 今年のクリスマスにハワイに行きます。 | 毎年 まいとし/まいねん every year: 毎年、父と母が日本に来ます。 | 2003 年 2003 ねん (the year of) 2003: 2003 年に日本に来ました。 | 来年 らいねん next year: 来年の六月にアメリカに行きます。 | 三年(間) さんねん（かん） three years: 三年（間）日本にいます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (56, '前', 'N5', 'まえ', 'ゼン', 'before', '前 まえ before: 今、九時五分前です。 in front of： 学校の前にスタバがあります。 | 三年前 さんねんまえ three years ago: 三年前に日本に来ました。 | 午ご 前 ごぜん morning; a.m.: 今、午ご 前十時です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (57, '後', 'N5', 'うし（ろ）、あと', 'ゴ', 'behind', '後ろ うしろ behind: テレビの後ろにスピーカーがあります。 | 後で あとで later: また後でメールします。 | 一年後 いちねんご one year after: 一年後にフランスに行きます。 | 午ご 後 ごご afternoon; p.m.: 今、午ご 後八時です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (58, '午', 'N5', '', 'ゴ', 'noon', '午前 ごぜん morning; a.m.: ミーティングは午前九時からです。 | 午後 ごご afternoon; p.m.: 土曜よ う日の午後は休みです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (59, '名', 'N5', 'な', 'メイ', 'name', '名前 なまえ name: こちらにお名前をおねがいします。 | 有ゆ う名 ゆうめい famous: あの人はとても有ゆ う名な先生です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (60, '車', 'N5', 'くるま', 'シャ', 'car', '車 くるま car: 父の車で来ました。 | 電でん車 でんしゃ train: 毎日電でん車で大学に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (61, '天', 'N5', '', 'テン', 'heaven; sky', '天気 てんき weather: 今日はいい天気ですね。 | 人気 にんき popularity: あの先生は人気があります。 | 気分 きぶん feeling: 今日は気分がよくないです。 | 気をつけます きをつけます take care; be careful: あぶない！気をつけてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (62, '気', 'N5', '', 'キ', 'mood; spirit; mind', '天気 てんき weather: 今日はいい天気ですね。 | 人気 にんき popularity: あの先生は人気があります。 | 気分 きぶん feeling: 今日は気分がよくないです。 | 気をつけます きをつけます take care; be careful: あぶない！気をつけてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (63, '電', 'N5', '', 'デン', 'electricity', '電気 でんき electricity: 電気をつけましょうか。 | 電車 でんしゃ train: 毎日、電車で学校に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (64, '話', 'N5', 'はな（します）、はなし', 'ワ', 'speak', '話します はなします speak: 会かい社し ゃで日本語ご を話します。 talk; tell： 友だちに話します。 | 話 はなし story: おもしろい話ですね。 | 電話 でんわ telephone: 今日、母に電話しました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (65, '食', 'N5', 'た（べます）', 'ショク', 'eat', '食べます たべます eat: このケーキを食べてもいいですか。 | 食堂ど う しょくどう dining room: 会かい社し ゃの食堂ど うでカレーを食べました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (66, '聞', 'N5', 'き（きます）, き（こえます）', 'ブン', 'hear', '聞きます ききます hear: 友だちにその話を聞きました。 listen： 車の中でラジオを聞きます。 ask： すみません。ちょっと聞いてもいいですか。 | 聞こえます きこえます be audible: すみません。よく聞こえません。 | 新し ん聞 しんぶん newspaper: これは三日前の新し ん聞です。 雨 電 gate ear 14 聞く 13');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (67, '書', 'N5', 'か（きます）', 'ショ', 'write', '書きます かきます write: ここに名前を書いてください。 | 図と 書館かん としょかん library: 今日の午後、図と 書館かんに行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (68, '読', 'N5', 'よ（みます）', 'ドク', 'read', '読みます よみます read: 毎日電車の中で新し ん聞を読みます。 | 読書 どくしょ reading: 母は読書が好す きです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (69, '国', 'N5', 'くに', 'コク', 'country', '国 くに country: あなたの国は、今何時ですか。 | 中国 ちゅうごく China: 中国に行きたいです。 | 国際さ い電話 こくさいでんわ international call: ニューヨークに国際さ い電話をかけました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (70, '外', 'N5', 'そと', 'ガイ', 'outside', '外 そと outside: 天気がいいですから、外で食べましょう。 | 外国 がいこく foreign country: 来月の休みに外国に行きます。 | 外国人 がいこくじん foreigner: 外国人の友だちがたくさんいます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (71, '語', 'N5', '', 'ゴ', 'language', '日本語 にほんご Japanese (language): 日本語で書いてください。 | 英えい語 えいご English (language): 電車の中で英えい語の新し ん聞を読みます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (72, '入', 'N5', 'い（れます）、はい（ります）', 'ニュウ', 'put in', '入れます いれます put in: ここにお金を入れてください。 | 入ります はいります enter: 入ってもいいですか。 join： スポーツクラブに入りました。 | 入学します にゅうがくします enter a school: 先月、大学に入学しました。 hand brush paper 書く');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (73, '出', 'N5', 'だ（します）、で（ます）', 'シュツ', 'take out', '出します だします take out: ポケットからお金を出します。 send： あした手て 紙がみを出します。 hand in： レポートを出してください。 | 出ます でます leave: 電車は九時に駅え きを出ます。 attend： 明日 あ し た、ミーティングに出ますか。 | 出かけます でかけます go out: 田中さんはもう出かけましたよ。 | 出発ぱつします しゅっぱつします leave; depart: 明日 あ し た、八時に出発ぱつしましょう。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (74, '雨', 'N5', 'あめ', '', 'rain', '雨 あめ rain: 今日の午後は雨です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (75, '東', 'N5', 'ひがし', 'トウ', 'east', '東 ひがし east: こちらが東です。 | 東京きょう とうきょう Tokyo: 東京きょうは人がたくさんいます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (76, '西', 'N5', 'にし', 'セイ、サイ', 'west', '西 にし west: あちらが西です。 | 西洋よ う せいよう the West; Western: 西洋よ うりょう料理り が好す きですか。 | 関かん西 かんさい the Kansai region: 関かん西に行ったことがありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (77, '南', 'N5', 'みなみ', 'ナン', 'south', '南 みなみ south: そちらが南です。 | 東南アジア とうなんアジア Southeast Asia: 東南アジアの国に行きたいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (78, '北', 'N5', 'きた', 'ホク', 'north', '北 きた north: どちらが北ですか。 | 東北 とうほく Tohoku region: 東北はとても寒さ むいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (79, '長', 'N5', 'なが（い）', 'チョウ', 'long; chief; head', '長い ながい long: 三時間のレッスンは長いです。 | 校長 こうちょう principal: これは校長先生の車です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (80, '高', 'N5', 'たか（い）', 'コウ', 'high', '高い たかい high: あのビルは高いです。 expensive： このレストランは高いです。 | 高校 こうこう high school: 高校で日本語を学びました。 | 高校生 こうこうせい high school student: 高校生の子どもが一人います。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (81, '口', 'N5', 'くち', 'コウ', 'mouth', '口 くち mouth: あの男の人は口が大きいです。 | 入いり口 いりぐち entrance: 右に入口があります。 | 出口 でぐち exit: 左に出口があります。 | 人口 じんこう population: 日本の人口は一億お く二千四百万人ぐらいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (82, '目', 'N5', 'め', '', 'eye', '目 め eye: あの女の人は目が大きいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (83, '手', 'N5', 'て', 'シュ', 'hand', '手 て hand: 手を洗あらいたいです。 arm： あの男の人は手が長いです。 | お手洗あらい おてあらい lavatory; rest room: すみません。お手洗あらいはどこですか。 | 運う ん転てん手 うんてんしゅ driver: バスの運う ん転てん手になりたいです。 | 上手ず じょうず skillful: 母はテニスがとても上手です。 | 下手 高 日 目 へ た へた poor; unskillful: 父はゴルフが下手です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (84, '足', 'N5', 'あし、た（ります）', '', 'foot', '足 あし foot: 足のサイズは何センチですか。 leg： あの男の子は足が長いです。 | 足ります たります enough: 一万円で足りますか。 16 日 口');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (85, '近', 'N5', 'ちか（い）', 'キン', 'close', '近い ちかい close: 中国と日本は近いです。 | 近く ちかく neighborhood: この近くにコンビニがありますか。 | 近所じ ょ きんじょ neighborhood: 近所じ ょに中学校があります。 | 最さ い近 さいきん recently: 最さ い近、どんな本を読みましたか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (86, '有', 'N5', 'あ（ります）', 'ユウ', 'exist', '有ります あります exist: 山に木がたくさん有ります。 （「あります」はあまり漢かん字じ で書きません。よくひらがなで書きます） | 有名 ゆうめい famous: 有名なレストランに行きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (87, '花', 'N5', 'はな', 'カ', 'lower', '花 はな ｆlower: あの川の近くに白い花がたくさんあります。 | 花屋や はなや ｆlower shop: 花屋や でアルバイトをしています。 | 花火 はなび fireworks: 今年は花火を見ましたか。 | 花びん かびん vase: 母の誕たん生日に花びんをあげました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (88, '赤', 'N5', 'あか（い）、あか', '', 'red', '赤い あかい red (adj.): 赤い花と白い花、どちらがすきですか。 | 赤 あか red (noun): わたし私は赤が好す きです。 | 赤ちゃん あかちゃん ｂaby: 赤ちゃん、かわいいですね。（＝赤ん坊ぼう）');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (89, '紙', 'N5', 'かみ', '', 'paper', '紙 かみ paper: すみません。紙を一枚まいください。 | 手紙 てがみ letter: 外国の友だちに毎月手紙を書きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (90, '買', 'N5', 'か（います）', '', 'buy', '買います かいます buy: 今月、大きいテレビを買いました。 | 買い物もの かいもの shopping: 母は買い物ものに行きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (91, '朝', 'N5', 'あさ', '', 'morning', '朝 あさ morning: 朝は天気がよかったです。 | 毎朝 まいあさ every morning: 毎朝、花に水をあげます。 | 今け 朝さ けさ this morning: 今朝は雨でした。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (92, '昼', 'N5', 'ひる', '', 'noon', '昼 ひる noon: あしたの昼に電話します。 | 昼ごはん ひるごはん lunch: 毎日十二時に昼ごはんを食べます。 | 昼間 ひるま daytime: 母は昼間、うちにいません。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (93, '夕', 'N5', 'ゆう', '', 'evening', '夕方がた ゆうがた evening: 今日の夕方がたに図と 書館かんに行きます。 | 夕飯はん ゆうはん dinner; supper: 夕飯はんは何時ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (94, '夜', 'N5', 'よる', 'ヤ', 'night', '夜 よる night: きのうの夜は何時に寝ね ましたか。 | 今夜 こんや tonight: 今夜いっしょに飲の みに行きませんか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (95, '私', 'N5', 'わたし、わたくし', '', 'I', '私 わたし I: 私は今日時間があります。 わたくし \[formal\] I： 私は田中と申も うします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (96, '家', 'N5', 'いえ', 'カ', 'house', '家 いえ house: 私の家は六ろ っ本ぽん木ぎ にあります。 | 家族ぞ く かぞく family: 私は六人家族ぞ くです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (97, '会', 'N5', 'あ（います）', 'カイ', 'see (a person)', '会います あいます see (a person): 明日 moon hill 夕 あ し た、友だちに会います。 | 会話 かいわ conversation: 会話が上手になりたいです。 | 会議ぎ かいぎ meeting: 今日の会議ぎ は午後二時からです。出ますか。 18');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (98, '社', 'N5', '', 'シャ', 'company', '会社 かいしゃ company: 土曜よ う日も会社に行きます。 | 社会 しゃかい society: 日本の社会について学びたいです。 | 社長 しゃちょう company president: 社長は今、出かけています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (99, '店', 'N5', 'みせ', 'テン', 'store; shop', '店 みせ store; shop: この店で本を買いました。 | 店員いん てんいん salesclerk; shop assistant: あの店の店員いんはきれいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (100, '飲', 'N5', 'の（みます）', '', 'drink', '飲みます のみます drink: コーヒーを飲みに行きませんか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (101, '多', 'N5', 'おお（い）', '', 'a lot of', '多い おおい a lot of: 東京きょうは車が多いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (102, '少', 'N5', 'すこ（し）、すく（ない）', 'ショウ', 'a little', '少し すこし a little: 少し＋\[verb\]： 少しビールを飲みました。 少し＋\[adj.\]： このシャツは少し大きいです。 | 少ない すくない not many/much: 私の家の近くは店が少ないです。 | 少々 しょうしょう a little \[formal\]: 少々お待ま ちください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (103, '古', 'N5', 'ふる（い）', '', 'old', '古い ふるい old: この電話は古いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (104, '新', 'N5', 'あたら（しい）', 'シン', 'new', '新しい あたらしい new: 先月デパートで新しいバッグを買いました。 | 新聞 しんぶん newspaper: これは日本語の新聞です。 19 wood ax');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (105, '広', 'N5', 'ひろ（い）', '', 'spacious', '広い ひろい spacious: 母の家はとても広いです。 wide： 学校の前の道みちは広いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (106, '安', 'N5', 'やす（い）', 'アン', 'cheap; inexpensive; peacefulness', '安い やすい inexpensive: この車は安いです。 | 安心し んします あんしんします feel relieved: 父から電話をもらって、安心し んしました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (107, '立', 'N5', 'た（ちます）', '', 'stand', '立ちます たちます stand: 男の人がコンビニの前に立っています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (108, '知', 'N5', 'し（ります）', '', 'know', '知ります しります know: あの女の人を知っていますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (109, '言', 'N5', 'い（います）、こと', 'ゴン', 'say', '言います いいます say: 山やま中なかさんは明日会社に来ると言いました。 tell： じゃ、大おおかわ川さんに言います。 | 言葉ば ことば word; language: その言葉ば を知っていますか。 | 伝でん言 でんごん message: 伝でん言をおねがいします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (110, '思', 'N5', 'おも（います）', '', 'think', '思います おもいます think: 日本の食べ物ものはおいしいと思います。 | 思い出します おもいだします recall; remember: あっ、思い出しました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (111, '歩', 'N5', 'ある（きます）', 'ホ', 'walk', '歩きます あるきます walk: きのう会社まで歩いて行きました。 | 散さ ん歩します さんぽします take a walk: 毎朝、この近くを三十分散さん歩します。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (112, '走', 'N5', 'はし（ります）', '', 'run', '走ります はしります run: 時間がありませんから、走りましょう。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (113, '住', 'N5', 'す（みます）', 'ジュウ', 'live; inhabit', '住みます すみます live; inhabit: 私は会社の近くに住んでいます。 | 住所し ょ じゅうしょ address: ここに、住所し ょと名前を書いてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (114, '空', 'N5', 'そら、あ（きます）', 'クウ', 'sky', '空 そら sky: 今日は空がきれいですね。 | 空きます あきます be vacant; be unoccupied: 今お手洗あらいは空いていますか。 | 空気 くうき air: 山の空気はおいしいです。 | 空港こ う くうこう airport: その空港こ うは、広くて新しいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (115, '週', 'N5', '', 'シュウ', 'week', '週 しゅう week: その週は、日本にいませんでした。 | 来週 らいしゅう next week: 来週私の家に来てください。 | 今週 こんしゅう this week: 今週は雨が多かったです。 | 二週間 にしゅうかん two weeks: 二週間会社を休みました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (116, '魚', 'N5', 'さかな', '', 'fish', '魚 さかな fish: 魚料りょう理り を食べました。 | 魚屋や さかなや fish store: 魚屋や は花屋や のとなりです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (117, '耳', 'N5', 'みみ', '', 'ear', '耳 みみ ear: うさぎ(rabbit)は耳が長いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (118, '銀', 'N5', '', 'ギン', 'silver', '銀 ぎん silver: 銀のスプーンを買いました。 | 銀行 ぎんこう bank: 銀行は三時までです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (119, '道', 'N5', 'みち', 'ドウ', 'road; street', '道 みち road; street: 家の前の道は広いです。 | 水道 すいどう waterworks; tap water: 水道の水はおいしくないです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (120, '駅', 'N5', '', 'エキ', 'station', '駅 えき station: 私の家は駅から歩いて十分です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (121, '曜', 'N4', '', 'ヨウ', 'day of the week', '土曜日 どようび Saturday: 土曜日は休みです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (122, '作', 'N4', 'つく（ります）', 'サク', 'make; produce', '作ります つくります make; produce: ここで車を作っています。 | 作文ぶん さくぶん composition: 日曜日の夜、作文ぶんを書きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (123, '使', 'N4', 'つか（います）', 'シ', 'use', '使います つかいます use: このペンを使ってもいいですか。 | 大使館かん たいしかん embassy: 土曜日に、大使館かんに行きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (124, '待', 'N4', 'ま（ちます）', '', 'wait', '待ちます まちます wait: 友だちを二時間待ちました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (125, '力', 'N4', 'ちから', 'リョク', 'power; strength', '力 ちから power; strength: 男は女より力があります。 | 能のう力 のうりょく ability: 今年の日本語能のう力試し 験けんはいつですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (126, '不', 'N4', '', 'フ', 'not; un-', '不便べん ふべん inconvenient: ここは電気がなくて、とても不便べんです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (127, '心', 'N4', 'こころ', 'シン', 'heart; mind', '心 こころ heart; mind: 父は心が広いです。 | 心配ぱいします しんぱいします worry: 心配ぱいしないでください。 | 安心します あんしんします be relieved: もうだいじょうぶですから、安心してください。 | 熱ねっ心 ねっしん eager; enthusiastic: あの先生は、とても熱ねっ心です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (128, '文', 'N4', '', 'ブン', 'sentence', '文 ぶん sentence: この文を読んでください。 | 文学 ぶんがく literature: 大学で文学を勉べんきょう強しました。 | 文化か ぶんか culture: 日本の文化か はおもしろいです。 | 文法ぽ う ぶんぽう grammar: 日本語の文法ぽ うはやさしいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (129, '元', 'N4', '', 'ゲン', 'origin; foundation', '元気 げんき healthy; well: お元気ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (130, '音', 'N4', 'おと', 'オン', 'sound', '音 おと sound: 車の音が聞こえます。 | 発はつ音 はつおん pronunciation: 日本語の発はつ音はやさしいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (131, '楽', 'N4', 'たの（しい）', 'ガク、ラク', 'pleasant; enjoyable', '楽しい たのしい pleasant; enjoyable: パーティーはとても楽しかったです。 | 楽しみ たのしみ pleasure: 明日のデートが楽しみです。(look forward to・・・) | 音楽 おんがく music: 毎日、電車の中で音楽を聞きます。 | 楽 らく easy: 私の仕し 事ご とは楽です。 comfortable： このソファは楽です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (132, '持', 'N4', 'も（ちます）', '', 'have', '持ちます もちます have: 車を持っていますか。 | お金持ち おかねもち a rich person: 山やま本も とさんはお金持ちです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (133, '映', 'N4', '', 'エイ', 'reflect; project', '映画 えいが movie; film: 日曜日、映画を見に行きませんか。 | 計けい画 けいかく plan: 社長はその計けい画を知っていますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (134, '画', 'N4', '', 'ガ、カク', 'picture', '映画 えいが movie; film: 日曜日、映画を見に行きませんか。 | 計けい画 けいかく plan: 社長はその計けい画を知っていますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (135, '料', 'N4', '', 'リョウ', 'material; fee', '料理り りょうり cooking: 母は料理り が上手です。 | 授じ ゅぎょう業料 じゅぎょうりょう tuition: 授じ ゅぎょう業料はいくらですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (136, '理', 'N4', '', 'リ', 'reason; logic; principle', '理由ゆ う りゆう reason: 理由ゆ うを話してください。 | 無む 理 むり impossible: それは無む 理です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (137, '方', 'N4', 'かた', 'ホウ', 'person (respect)', '方 かた person (respect): この方を知っていますか。 | ～方 ～かた how to ... ; way of ...: 書き方を教お しえてください。 | 夕方 ゆうがた evening: 明日の夕方五時に電話します。 | 方 ほう direction; side: 右の方に行ってください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (138, '台', 'N4', '', 'ダイ、タイ', 'stand; pedestal; base', '～台 ～だい counter for machinery: 私は車を二台持っています。 | 台所どころ だいどころ kitchen: 母は今、台所どころで料理をしています。 | 台風ふ う たいふう typhoon: 来週、台風が来ます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (139, '字', 'N4', '', 'ジ', 'letter', '字 じ letter: この字の読み方を知っていますか。 | ローマ字 ローマじ romaji; roman letters: ローマ字の文は読みにくいです。 | 漢かん字 かんじ kanji; Chinese character: 漢かん字はおもしろいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (140, '主', 'N4', '', 'シュ', 'main', '主人 しゅじん husband: 主人はアメリカにいます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (141, '以', 'N4', '', 'イ', 'except (for)', '以外 いがい except (for): 金曜以外は時間があります。 | 以内ない いない within: 千字以内ないの作文を書いてください。 | 以上 いじょう ... or more than: 三十分以上待ちました。 | 以下 いか ... or less than: 十二歳さ い以下は千円です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (142, '去', 'N4', '', 'キョ', 'leave; go away', '去年 きょねん last year: 去年の夏に日本に来ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (143, '正', 'N4', 'ただ（しい）', 'ショウ', 'right; correct', '正しい ただしい right; correct: この漢かん字は正しいですか。 | 正月 しょうがつ the New Year: 毎年、正月にハワイに行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (144, '田', 'N4', 'た', '', 'rice field', '山田 やまだ Yamada (surname): こちらは山田さんです。 | 田中 たなか Tanaka (surname): あちらは田中さんです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (145, '同', 'N4', 'おな（じ）', '', 'same', '同じ おなじ same: 私の車は田中さんのと同じです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (146, '早', 'N4', 'はや（い）', '', 'early', '早い はやい early (adj.): 「朝６時に来てください」、「早いですね」 | 早く はやく early (adv.): 私は毎朝早く起お きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (147, '明', 'N4', 'あか（るい）', 'メイ', 'bright', '明るい あかるい bright: この店は明るいですね。 | 明日 あした/あす tomorrow: 明日の朝早く出かけます。 | 説せつ明します せつめいします explain: 日本語で説せつ明してください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (148, '牛', 'N4', 'うし', 'ギュウ', 'cow; bull; cattle', '牛 うし cow; bull; cattle: あそこに牛がたくさんいます。 | 牛にゅう 乳ぎゅうにゅう milk: 毎朝、牛にゅう乳を飲みます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (149, '肉', 'N4', '', 'ニク', 'meat', '肉 にく meat: 肉より魚の方が好す きです。 | 牛肉 ぎゅうにく beef: スーパーで牛肉を買いました。 | ぶた豚肉 ぶたにく pork: ぶた豚肉の料理が好す きです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (150, '世', 'N4', '', 'セ', 'world', '世話 せわ care: いつもお世話になっています。 (We are under the care of you/your company.)');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (151, '界', 'N4', '', 'カイ', 'world', '世界 せかい world: あれは世界一高いビルです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (152, '仕', 'N4', '', 'シ', 'serve a person; work under somebody', '仕方がない しかたがない It can’t be helped. / There’s no help for it.: 仕方がありませんね。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (153, '事', 'N4', 'こと', 'ジ', 'thing; matter', '事 こと thing; matter: その事を知っていましたか。 | 仕事 しごと work: 今日は仕事がたくさんあります。 | 火事 かじ fire: 火事です！１１９ばん番に電話してください。 | 食事 しょくじ meal: 明日、食事に行きませんか。 | 大事 だいじ important: 明日、大事な会議ぎ があります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (154, '工', 'N4', '', 'コウ', 'manufacturing; construction', '工事 こうじ construction: ガスの工事はいつからですか。 | 工事中 こうじちゅう under construction: ここは今工事中です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (155, '場', 'N4', 'ば', 'ジョウ', 'place', '場所し ょ ばしょ place: 場所し ょと時間は後でメールします。 | 工場 こうじょう factory: あれはビール工場です。 | ゴルフ場 ゴルフじょう golf course: 広いゴルフ場ですね。 | ボーリング場 ボーリングじょう bowling alley: きれいなボーリング場ですね。 | ちゅう駐車場 ちゅうしゃじょう car park; parking lot: この近くにちゅう駐車場がありますか。 | 会場 かいじょう meeting place; hall: パーティーの会場はどこですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (156, '屋', 'N4', 'や', 'オク', 'store/shop', '～屋 ～や ... store/shop: 本屋で新聞を買いました。 | 八や 百お 屋 やおや vegetable store: 八百屋でりんごを三つ買いました。 | 屋上 おくじょう the roof top: 屋上でバーベキューをしましょう。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (157, '旅', 'N4', '', 'リョ', 'trip, travel', '旅行 りょこう travel: ヨーロッパを旅行したいです。 | 旅館かん りょかん Japanese inn: 旅館かんで日本料理を食べました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (158, '動', 'N4', 'うご（きます）', 'ドウ', 'move', '動きます うごきます move: 動かないでください。 | 自じ 動車 じどうしゃ car: 子どもは自じ 動車のおもちゃ（toy）が好す きです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (159, '勉', 'N4', '', 'ベン', 'effort, hard work', '強い つよい strong: あの人は力が強いです。 | 勉強します べんきょうします study: 毎日一時間以上勉強します。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (160, '強', 'N4', 'つよ（い）', 'キョウ', 'strong', '強い つよい strong: あの人は力が強いです。 | 勉強します べんきょうします study: 毎日一時間以上勉強します。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (161, '考', 'N4', 'かんが（えます）', '', 'think; consider', '考えます かんがえます think; consider: よく考えてから電話します。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (162, '送', 'N4', 'おく（ります）', '', 'send', '送ります おくります send: 今朝、会社にＦＡＸを送りました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (163, '売', 'N4', 'う（ります）、う（れます）', '', 'sell', '売ります うります sell (vt.): どこで新聞を売っていますか。 | 売り場 うりば lit. selling place: カメラ売り場はどこですか。 | 売れます うれます sell (vi.): 今年はビールが売れませんでした。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (164, '始', 'N4', 'はじ（めます）、はじ（まります）', '', 'start, begin', '始めます はじめます start; begin (vt.): 九時に仕事を始めます。 | 始まります はじまります start; begin (vi.): パーティーはもう始まりましたか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (165, '終', 'N4', 'お（わります）', '', 'finish; end', '終わります おわります finish; end: 今、レッスンが終わりました。 | 終わり おわり the end: 八月の終わりに旅行に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (166, '計', 'N4', '', 'ケイ', 'measure; arrange', '時と 計 とけい watch; clock: ハワイに行った時、この時計を買いました。 | 計画 けいかく plan: この計画についてどう思いますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (167, '兄', 'N4', 'あに', 'キョウ', '(my) elder brother', '兄 あに (my) elder brother: 兄は中学校の先生です。 | お兄にいさん おにいさん (someone’s) elder brother: お兄さんはいますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (168, '弟', 'N4', 'おとうと', 'ダイ', '(my) younger brother', '弟 おとうと (my) younger brother: 弟が二人います。 | 弟さん おとうとさん (someone’s) younger brother: 弟さんは何歳さ いですか。 | 兄弟 きょうだい brothers: 兄弟は何人いますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (169, '姉', 'N4', 'あね', '', '(my) elder sister', '姉 あね (my) elder sister: 日曜日、姉と映画を見に行きました。 | お姉ねえさん おねえさん (someone’s) elder sister: お姉さんはお元気ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (170, '妹', 'N4', 'いもうと', '', '(my) younger sister', '妹 いもうと (my) younger sister: 妹は料理が上手です。 | 妹さん いもうとさん (someone’s) younger sister: 妹さんのお仕事は何ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (171, '代', 'N4', 'か（わります）', 'ダイ', 'age; generation; price', '代わりに かわりに on behalf of ...: 私の代わりに中山さんが行きます。 | 時代 じだい time; period: 学生時代、よく旅行しました。 | 六十年代 ろくじゅうねんだい the 60’s: 六十年代の音楽をよく聞きます。 | ～代 ～だい charge; fee: 今月の電気代は高かったです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (172, '用', 'N4', '', 'ヨウ', 'business; something to do', '用 よう business; something to do: 用があるので、早く帰ります。 | 用事 ようじ business; something to do: 明日は、用事があります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (173, '自', 'N4', '', 'ジ', 'self', '自分 じぶん oneself: この時計は自分で買いました。 | 自動車 じどうしゃ car: 子どもに自動車のおもちゃ（toy）を買いました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (174, '地', 'N4', '', 'チ、ジ', 'earth; land', '地下 ちか underground; basement: 肉売り場は地下です。 | 地震し ん じしん earthquake: 今朝、大きい地震し んがありました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (175, '図', 'N4', '', 'ズ、ト', 'drawing; diagram; chart; figure', '図 ず drawing; diagram; chart; figure: 図を見て考えてください。 | 地図 ちず map: 地図を見て友だちの家に行きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (176, '館', 'N4', '', 'カン', 'building; hall', '旅館 りょかん Japanese inn: 旅館までの地図を FAX してください。 | 大使館 たいしかん embassy: 来週、大使館に行かなければなりません。 | 図書館 としょかん library: その図書館には日本語のテキストもあります。 | 映画館 えいがかん movie theater: 妹と六ろ っぽん本木ぎ の映画館に行きました。 | 美び じゅつ術館 びじゅつかん art gallery; museum of art: 美び じゅつ術館に行きませんか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (177, '英', 'N4', '', 'エイ', 'Great Britain/the U.K.', '英語 えいご English (language): 英語が話せますか。 | 英会話 えいかいわ English conversation: 週に一回、英会話学校に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (178, '鉄', 'N4', '', 'テツ', 'iron', '鉄 てつ iron: これは鉄ですか。プラスチックですか。 | 地下鉄 ちかてつ subway; underground: 毎日、地下鉄で会社に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (179, '町', 'N4', 'まち', '', 'town', '町 まち town: 私はカリフォルニアの小さい町で生まれました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (180, '京', 'N4', '', 'キョウ', 'the capital', '東京 とうきょう Tokyo: 東京は人も車も多いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (181, '味', 'N4', 'あじ', 'ミ', 'taste; flavor', '味 あじ taste; flavor: どんな味がしますか。 | 意い 味 いみ meaning: 「工事中」ってどういう意い 味ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (182, '度', 'N4', '', 'ド', 'times; degree', '一度 いちど once: もう一度言ってください。 | 今度 こんど next time: 今度の日曜日、食事に行きませんか。 some time： 今度、私の家に来ませんか。 this time： 今度のテストはよくできました。 | 二十五度 にじゅうごど 25 degrees: 今日は二十五度ぐらいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (183, '風', 'N4', 'かぜ', 'フウ', 'wind', '風 かぜ wind: 今日は風が強いですね。 | 台風 たいふう typhoon: 夏は台風が多いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (184, '洋', 'N4', '', 'ヨウ', 'ocean', '洋服ふ く ようふく clothes: 姉は洋服ふ くをたくさん持っています。 | 洋食 ようしょく Western food: 妹は洋食が好す きです。 | 西洋 せいよう the West; Western: 西洋の文学を勉強しています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (185, '茶', 'N4', '', 'チャ', 'tea', 'お茶 おちゃ tea: お茶を飲みませんか。 | 茶わん ちゃわん (rice) bowl: この古い茶わんは三万円で買いました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (186, '鳥', 'N4', 'とり', '', 'bird', '鳥 とり bird: 木の上に鳥がたくさんいます。 | 小鳥 ことり small bird: 友だちの家に白い小鳥がいます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (187, '堂', 'N4', '', 'ドウ', 'hall', '食堂 しょくどう dining room: 毎日、会社の食堂で昼ごはんを食べます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (188, '室', 'N4', '', 'シツ', 'room', 'きょう教室 きょうしつ classroom: この学校の教きょう室は広くてきれいです。 | 会議ぎ 室 かいぎしつ meeting room: 今、この会議ぎ 室は空いていますか。 | 洋室 ようしつ Western-style room: その旅館に洋室がありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (189, '色', 'N4', 'いろ', '', 'color', '色 いろ color: 明るい色のカーテンがほしいです。 | 茶色 ちゃいろ brown: 茶色のブーツを買いました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (190, '青', 'N4', 'あお（い）、あお', '', 'blue', '青い あおい blue (adj.): 目が青いねこを見ました。 | 青 あお blue (noun): 信し ん号ご う（traffic light）が青になりました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (191, '黒', 'N4', 'くろ（い）、くろ', '', 'black', '黒い くろい black (adj.): 黒いペンで書いてください。 | 黒 くろ black (noun): 私は色は黒が好す きです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (192, '品', 'N4', 'しな', 'ヒン', 'article; goods', '品川 しながわ Shinagawa (a name of town): 兄は品川に住んでいます。 | 食料品 しょくりょうひん foodstuffs; groceries: 一週間に一回かい、食料品を買います。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (193, '物', 'N4', 'もの', 'ブツ', 'object; article', '物 もの object; article: 今一番ばんほしい物は何ですか。 | 品物 しなもの goods; selling item: この店は品物が多いです。 | 買い物 かいもの shopping: 外国に行くと、いつもたくさん買い物します。 | 食べ物 たべもの food: 何か食べ物を買って来てください。 | 飲み物 のみもの drink; beverage: 飲み物は何がいいですか。 | 動物 どうぶつ animal: くじら（whale）は魚じゃなくて、動物です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (194, '注', 'N4', '', 'チュウ', 'pour; flow', '注射し ゃ ちゅうしゃ injection: 明日、注射し ゃをしなければなりません。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (195, '意', 'N4', '', 'イ', 'will; mind; meaning', '用意 ようい preparation: 旅行の用意はできましたか。 | 意見 いけん opinion: 何も意見がなければ、これで終わります。 | 注意します ちゅういします pay attention; take care: 車に注意してください。 advise; warn： たばこを吸す っている人に注意しました。 | 意味 いみ meaning: 「ひさしぶり」ってどういう意味ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (196, '医', 'N4', '', 'イ', 'medicine', '医学 いがく medical science; medicine: 大学で西洋医学を勉強しました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (197, '者', 'N4', 'もの', 'シャ', 'person (humble)', '者 もの person (humble): 会社の者がそちらにお電話します。 | 医者 いしゃ doctor: 子どもの時、医者になりたかったです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (198, '病', 'N4', '', 'ビョウ', 'sickness; illness', '病気 びょうき sickness; illness; disease: 先週、病気で会社を休みました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (199, '院', 'N4', '', 'イン', 'institution', '病院 びょういん hospital: 病院に行くので、早く帰ります。 | 入院します にゅういんします be hospitalized: 妹は今、入院しています。 | 退たい院します たいいんします leave hospital: 妹は来週、退たい院できると思います。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (200, '急', 'N4', 'いそ（ぎます）', 'キュウ', 'hurry', '急ぎます いそぎます hurry: 時間がないので急いでください。 | 急行 きゅうこう express: 今度の電車は品川行き（bound for～）の急行です。 | 急に きゅうに suddenly: 急に円が高くなりました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (201, '春', 'N4', 'はる', '', 'spring', '春 はる spring: 毎年、春に花見をします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (202, '夏', 'N4', 'なつ', '', 'summer', '夏 なつ summer: 今年の夏に会社でハワイに行きます。 | 夏休み なつやすみ summer vacation: 来週から夏休みが始まります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (203, '秋', 'N4', 'あき', '', 'fall; autumn', '秋 あき fall; autumn: 去年の秋に友だちとキャンプをしました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (204, '冬', 'N4', 'ふゆ', '', 'winter', '冬 ふゆ winter: 毎年、冬にカナダにスキーに行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (205, '親', 'N4', 'おや', 'シン', 'parent; close', '親 おや parent: 私の親は医者です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (206, '切', 'N4', 'き（ります）', 'セツ', 'cut', '切ります きります cut: 料理をしている時、手を切りました。 | 切手 きって stamp: 手紙を送りたいので、切手を買って来てください。 | 親切 しんせつ kind: その店の人たちはとても親切です。 | 大切 たいせつ important: 毎日、勉強することが大切です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (207, '特', 'N4', '', 'トク', 'special', '特に とくに specially: この映画は特におもしろいですよ。 | 特急 とっきゅう special express: 急行より特急の方が早いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (208, '別', 'N4', 'わか（れます）', 'ベツ', 'part; separate', '別れます わかれます part; separate: 三日前にボーイフレンドと別れました。 | 別 べつ another; different: 今日は雨ですから別の日にしましょう。 separately： 食べ物と飲み物は別に入れてください。 | 特別 とくべつ special: 今日は特別な日ですから、ケーキを買いました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (209, '写', 'N4', 'うつ（します）', 'シャ', 'take; photograph', '写します うつします take; photograph: これはデジカメで写しました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (210, '真', 'N4', 'ま', 'シン', 'truth; exactly; reality', '真ん中 まんなか middle; center: テーブルの真ん中に花があります。 | 写真 しゃしん photograph: 今度、兄弟の写真を見せてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (211, '運', 'N4', 'はこ（びます）', 'ウン', 'carry; transport', '運びます はこびます carry; transport: 買った物を車まで運んでください。 | 運 うん luck: 中山さんは運がいい人だと思います。 | 運動します うんどうします exercise: 毎朝、運動してから会社に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (212, '転', 'N4', 'ころ（びます）', 'テン', 'roll; fall down', '転びます ころびます fall down: 道で転んで、足にけがをしました。 | 自転車 じてんしゃ bicycle: 新しい自転車がほしいです。 | 運転します うんてんします drive: 父も母も車を運転します。 | 運転手 うんてんしゅ driver: 兄の仕事はタクシーの運転手です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (213, '質', 'N4', '', 'シツ', 'asking', '質問 しつもん question: 何か質問がありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (214, '問', 'N4', '', 'モン', 'question', '質問 しつもん question: 何か質問がありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (215, '題', 'N4', '', 'ダイ', 'topic; theme', '問題 もんだい question: テストの問題は三つあります。 problem： 問題があったらメールをください。 | しゅく宿題 しゅくだい homework: しゅく宿題をする時間がありませんでした。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (216, '答', 'N4', 'こた（えます）、こた（え）', '', 'answer', '答えます こた（えます） answer (verb): 私の質問に答えてください。 | 答え こた（え） answer (noun): その問題の答えがわかりますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (217, '教', 'N4', 'おし（えます）', 'キョウ', 'teach', '教えます おしえます teach: 姉は高校で英語を教えています。 | 教室 きょうしつ classroom: 今、この教室は空いていますか。 | 教育い く きょういく education: 子どもの教育い くは大切です。 | 教会 きょうかい church: 毎週日曜日、近くの教会に行きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (218, '習', 'N4', 'なら（います）', 'シュウ', 'learn', '習います ならいます learn: 週に一回、料理を習っています。 | 予よ 習します よしゅうします prepare for the lesson: 毎日予よ 習しています。 | 復ふ く習します ふくしゅうします review: 来週テストがあるので復ふ く習しようと思います。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (219, '起', 'N4', 'お（きます）、お（こします）', '', 'get/wakeup', '起きます おきます get/wake up (vi.): 今朝、何時に起きましたか。 | 起こします おこします get/wake somebody up (vt.): 七時に起こしてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (220, '死', 'N4', 'し（にます）', '', 'die', '死にます しにます die: 去年、ペットの鳥が死んでしまいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (221, '悪', 'N4', 'わる（い）', '', 'bad', '悪い わるい bad: 私は目が悪いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (222, '重', 'N4', 'おも（い）', '', 'heavy', '重い おもい heavy: これは重くて一人で運べません。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (223, '発', 'N4', '', 'ハツ', 'emit; depart', '発音 はつおん pronunciation: 「ら」の発音に注意してください。 | 出発します しゅっぱつします depart: 明日、何時に出発しますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (224, '帰', 'N4', 'かえ（ります）', '', 'return', '帰ります かえります return: ご主人が帰ったら電話をください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (225, '通', 'N4', 'とお（ります）、かよ（います）', '', 'go through; pass', '通ります とおります go through; pass: この道を通ったことがあります。 | 通り とおり road; street: この通りにはいい店がたくさんあります。 | 通います かよいます go to (school/work); commute: 車で会社に通っています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (226, '開', 'N4', 'あ（けます）、あ（きます）', '', 'open', '開けます あけます open (vt.): 風が強いので、ドアを開けないでください。 | 開きます あきます open (vi.): その店は何時に開きますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (227, '集', 'N4', 'あつ（めます）、あつ（まります）', '', '); collect', '集めます あつめます gather (vt.); collect: 外国の切手を集めています。 | 集まります あつまります gather (vi.): 店の前に人が集まっています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (228, '歌', 'N4', 'うた（います）、うた', '', 'sing', '歌います うたいます sing: カラオケで日本語の歌を歌いました。 | 歌 うた song: この歌を聞いたことがありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (229, '着', 'N4', 'き（ます）、つ（きます）', '', 'put on; wear', '着ます きます put on; wear: このスーツを着てみてもいいですか。 | 下着 したぎ underwear: 下着売り場はどこですか。 | 着きます つきます arrive; reach: この電車は何時に東京に着きますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (230, '貸', 'N4', 'か（します）', '', 'lend', '貸します かします lend: お金が足りないので、少し貸してください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (231, '借', 'N4', 'か（ります）', '', 'borrow', '借ります かります borrow: 銀行で五百万円借りました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (232, '犬', 'N4', 'いぬ', '', 'dog', '犬 いぬ dog: 子どもの時、家に大きい犬がいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (233, '服', 'N4', '', 'フク', 'clothes', '服 ふく clothes: その服、どこで買ったんですか。 | 洋服 ようふく (western) clothes: 姉に借りた洋服を着て行きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (234, '建', 'N4', 'た（てます）、た（ちます）', '', 'build', '建てます たてます build: 五年後に東京に家を建てたいです。 | 建ちます たちます be built: 駅の前に大きいビルが建ちました。 | 建たて物 たてもの building: 品川は高い建物が多いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (235, '海', 'N4', 'うみ', 'カイ', 'sea; ocean', '海 うみ sea; ocean: 夏休みに海に行くつもりです。 | 海岸がん かいがん seashore: いい天気だったので、犬と海岸がんを走りました。 | 海外 かいがい overseas: お正月に海外旅行したいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (236, '員', 'N4', '', 'イン', 'member', '店員 てんいん salesclerk: その店の店員はとても親切です。 | 会社員 かいしゃいん office worker: 父は会社員です。 | 銀行員 ぎんこういん bank clerk: ATM の使い方を銀行員に聞きました。 | 駅員 えきいん station employee: 行き方を駅員に教えてもらいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (237, '族', 'N4', '', 'ゾク', 'family', '家族 かぞく family: いつも家族の写真を持っています。 | 水族館 すいぞくかん aquarium: 日曜日、家族と水族館に行きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (238, '飯', 'N4', '', 'ハン', 'coked rice; meal; food', 'ご飯 ごはん cooked rice: パンとご飯とどちらをよく食べますか。 | 夕飯 ゆうはん dinner; supper: 毎日、夕飯の前に一時間勉強します。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (239, '野', 'N4', '', 'ヤ', 'field; plain', '野菜 やさい vegetable: あの八や 百お 屋は野菜が安いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (240, '菜', 'N4', '', 'サイ', 'vegetable', '野菜 やさい vegetable: あの八や 百お 屋は野菜が安いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (241, '止', 'N4', 'と（めます）、と（まります）', 'シ', 'stop', '止めます とめます stop (vt.): 運転手さん、駅の前で止めてください。 | 止まります とまります stop (vi.): 台風で電車が止まりました。 | 中止 ちゅうし cancellation: 明日のパーティーは中止です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (242, '漢', 'N4', '', 'カン', 'China', '漢字 かんじ kanji; Chinese character: この漢字はどう読みますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (243, '研', 'N4', '', 'ケン', 'whet; sharpen', '研究します けんきゅうします research; study: 兄は大学で動物の研究をしています。 | 研究室 けんきゅうしつ study room: 三時まで研究室で待っていてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (244, '究', 'N4', '', 'キュウ', 'investigate', '研究します けんきゅうします research; study: 兄は大学で動物の研究をしています。 | 研究室 けんきゅうしつ study room: 三時まで研究室で待っていてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (245, '試', 'N4', '', 'シ', 'try; attempt', '試験 しけん examination; test: 日本語能の う力試験は十二月です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (246, '験', 'N4', '', 'ケン', 'testing', '試験 しけん examination; test: 日本語能の う力試験は十二月です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (247, '内', 'N4', '', 'ナイ', 'inside', '以内 いない within: 田中さんは五分以内に来ると思います。 | 国内 こくない domestic: 海外旅行は高いので、国内旅行にしましょう。 | 家内 かない (my) wife: 家内は車の運転が上手です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (248, '体', 'N4', 'からだ', '', 'body', '体 からだ body: あの体が大きい人はだれですか。 | 体にいい からだにいい good for health: スポーツは体にいいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (249, '全', 'N4', '', 'ゼン', 'all; whole', '全員 ぜんいん all the members: 私の会社の人は、全員英語が話せます。 | 安全 あんぜん safe: 日本は安全な国だと思いますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (250, '回', 'N4', 'まわ（ります）', 'カイ', 'turn; go round', '回ります まわります turn; go round: レバーを上げると、モーターが回ります。 | 三回 さんかい three times: その水族館に三回行ったことがあります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (251, '所', 'N4', 'ところ', 'ショ', 'place', '所 ところ place: 山田さんの生まれた町はどんな所ですか。 | 台所 だいどころ kitchen: 中田さんの家の台所はとても広いです。 | 住所 じゅうしょ address: 社長の住所を知っていますか。 | 近所 きんじょ neighborhood: 近所の子どもたちが集まっています。 | 事務む 所 じむしょ office: 事務む 所までの行き方を教えてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (252, '公', 'N4', '', 'コウ', 'public; official', '公園 こうえん park: 公園を通って家に帰ります。 | 動物園 どうぶつえん zoo: 動物園でパンダの赤ちゃんを見ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (253, '園', 'N4', '', 'エン', 'garden', '公園 こうえん park: 公園を通って家に帰ります。 | 動物園 どうぶつえん zoo: 動物園でパンダの赤ちゃんを見ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (254, '利', 'N4', '', 'リ', 'benefit; advantage', '利用します りようします make use of: この公園は夕方五時まで利用できます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (255, '便', 'N4', '', 'ベン', 'convenience', '便利 べんり convenient; useful: ここは駅から近くて便利ですね。 | 不便 ふべん inconvenient: ここは電気も水道もなくてとても不便です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (256, '頭', 'N4', 'あたま', '', 'head', '頭 あたま head: 頭が痛いたかったので、会社を休みました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (257, '部', 'N4', '', 'ブ', 'part; section; department; copy of a publication', '全部 ぜんぶ all: この本は全部読みました。 | 部長 ぶちょう the head/chief of a department: 部長と夕飯を食べました。 | 学部 がくぶ faculty; department: 学部はどちらですか。 | ～部 ～ぶ copy: これを二十部コピーしてください。 | 部へ 屋 へや room: 私の家は部屋が四つあります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (258, '祖', 'N4', '', 'ソ', 'ancestor', '祖父 そふ grandfather: 祖父に旅行の写真を送りました。 | 祖母 そぼ grandmother: 祖母は今、入院しています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (259, '業', 'N4', '', 'ギョウ', 'occupation; business; work', '工業 こうぎょう industry: 妹はイギリスの工業について勉強しています。 | 授じ ゅ業 じゅぎょう class; lesson: 病気で、授じ ゅ業を休みました。 | 卒そつ業します そつぎょうします graduate: 弟は去年大学を卒そつ業しました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (260, '太', 'N4', 'ふと（い）、ふと（ります）', '', 'thick', '太い ふとい thick: ぞう(elephant)の足は太いです。 | 太ります ふとります gain weight: 食べすぎて、太ってしまいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (261, '低', 'N4', 'ひく（い）', '', 'low', '低い ひくい low: このテーブルは低いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (262, '短', 'N4', 'みじか（い）', '', 'short', '短い みじかい short: 一時間のレッスンは短いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (263, '好', 'N4', 'す（き）', '', 'like; be fond of', '好き すき like; be fond of: どんな歌が好きですか。 | 大好き だいすき be very fond of: 家内は買い物が大好きです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (264, '若', 'N4', 'わか（い）', '', 'young', '若い わかい young: 若い時、よく映画を見ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (265, '弱', 'N4', 'よわ（い）', '', 'weak', '弱い よわい weak: 女性は男性より力が弱いです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (266, '軽', 'N4', 'かる（い）', '', 'light', '軽い かるい light: これは軽いので、一人で持てます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (267, '遠', 'N4', 'とお（い）', '', 'far', '遠い とおい far: 私の家は、駅から遠いので不便です。 | 遠く とおく distant place: 山田さんは遠くから会社に通っています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (268, '暑', 'N4', 'あつ（い）', '', 'hot (weather)', '暑い あつい hot (weather): 今日は暑いですね。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (269, '寒', 'N4', 'さむ（い）', '', 'cold (weather)', '寒い さむい cold (weather): 今日、外は寒いですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (270, '合', 'N4', 'あ（います）', '', 'fit; suit; match', '合います あいます fit; suit; match: この服とこのくつは、よく合います。 | 間に合います まにあいます be in time: 出発の時間に間に合わないかもしれません。 | 場合あい ばあい case: 行けない場合は電話してください。 | 試合あい しあい match; game: 日曜日、サッカーの試合があります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (271, '伝', 'N4', 'つた（えます）', 'デン', 'tell; inform', '伝えます つたえます tell; inform: 部長に明日の会議ぎ の時間を伝えてください。 | 伝言 でんごん message: 伝言をおねがいします。 | 手伝います てつだいます help: 今日は仕事が多いので、手伝ってもらえませんか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (272, '決', 'N4', 'き（めます）、き（まります）', '', 'decide', '決めます きめます decide: いつ国に帰るか、まだ決めていません。 | 決まります きまります be decided: 来週のスケジュールは決まりましたか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (273, '困', 'N4', 'こま（ります）', '', 'have difficulty; be in trouble', '困ります こまります have difficulty; be in trouble: お金がなくて困っています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (274, '返', 'N4', 'かえ（します）', 'ヘン', 'return; give something back', '返します かえします return; give something back: 図書館に本を返しましたか。 | 返事 へんじ reply; answer: できるだけ早く返事をください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (275, '泳', 'N4', 'およ（ぎます）', 'エイ', 'swim', '泳ぎます およぎます swim: 週に一回スポーツクラブで泳いでいます。 | 水泳 すいえい swimming: 私の子どもは水泳を習っています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (276, '消', 'N4', 'け（します）、き（えます）', '', 'put out', '消します けします put out: 火を消してください。 turn off： テレビを消しましょうか。 erase： 消しゴム(eraser)で、字を消します。 | 消えます きえます go out: 風が強くて、火が消えました。 go off： 会議ぎ 室の電気が消えていますね。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (277, '忘', 'N4', 'わす（れます）', '', 'forget', '忘れます わすれます forget: この漢字は、勉強したのに忘れてしまいました。 forget to take, leave： 家にかぎを忘れました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (278, '呼', 'N4', 'よ（びます）', '', 'call', '呼びます よびます call: 病院に行くので、タクシーを呼んでください。 invite： 友だちをパーティーに呼びました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (279, '閉', 'N4', 'し（めます）、し（まります）', '', 'close', '閉めます しめます close (vt.): 夜になったら、カーテンを閉めてください。 | 閉まります しまります close (vi.): ドアが閉まりますから注意してください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (280, '引', 'N4', 'ひ（きます）', '', 'pull', '引きます ひきます pull: レバーを引くと、ドアが開きます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (281, '押', 'N4', 'お（します）', '', 'push', '押します おします push: このスイッチを押すと電気がつきます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (282, '拾', 'N4', 'ひろ（います）', '', 'pick up', '拾います ひろいます pick up: 道で一万円拾いました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (283, '捨', 'N4', 'す（てます）', '', 'throw away', '捨てます すてます throw away: ここにごみを捨てないでください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (284, '説', 'N4', '', 'セツ', 'opinion; theory', '説明します せつめいします explain: もう一度、説明してください。 | 小説 しょうせつ novel: 大学生の時、よく小説を読みました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (285, '受', 'N4', 'う（けます）、う（かります）', '', 'receive', '受けます うけます receive: 会社でトレーニングを受けました。 take (an exam)： 日本語能の う力試験三きゅう級を受けます。 | 受かります うかります pass (an exam): 日本語能のう力試験三きゅう級に受かりました。 | 受付つけ うけつけ reception: この病院の受付つけの人は親切です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (286, '取', 'N4', 'と（ります）', '', 'take', '取ります とります take: 好きなのを一つ取ってください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (287, '席', 'N4', '', 'セキ', 'seat', '席 せき seat: この席は空いていますか。 | 出席します しゅっせきします attend: 今日の会議ぎ に出席する人は何人ですか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (288, '連', 'N4', 'つ（れます）', '', 'take (someone)', '連れて行きます つれていきます take (someone): 友だちを病院に連れて行きました。 | 連れて来ます つれてきます bring (someone): 今度、主人を連れて来ます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (289, '座', 'N4', 'すわ（ります）', '', 'sit down', '座ります すわります sit down: このいすは低くて座りにくいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (290, '変', 'N4', 'か（えます）、か（わります）', 'ヘン', 'change', '変えます かえます change (vt.): 部屋のカーテンの色を変えました。 | 変わります かわります change (vi.): パーティーの場所が変わりました。 | 変 へん odd; strange: あの人は変な服を着ています。 | 大変 たいへん hard; serious: 今日は仕事が多くて大変です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (291, '乗', 'N4', 'の（ります）', '', 'get on', '乗ります のります get on: 駅前でタクシーに乗りました。 | 乗り物 のりもの vehicle; vessel: 駅からどんな乗り物がありますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (292, '降', 'N4', 'お（ります）、ふ（ります）', '', 'get off', '降ります おります get off: バスを降りてから十分ぐらい歩きます。 | 降ります ふります fall (rain; snow): 今、雨が降っていますか。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (293, '働', 'N4', 'はたら（きます）', '', 'work', '働きます はたらきます work: 外国で働きたいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (294, '残', 'N4', 'のこ（します）、のこ（ります）', 'ザン', 'leave', '残します のこします leave: 残さないで全部食べてください。 | 残ります のこります remain; be left: 食べ物がたくさん残りました。 | 残念ねん ざんねん unfortunate; regrettable; disappointing: 残念ねんですね。 | 残業します ざんぎょうします work overtime: 今日も残業しなければなりません。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (295, '調', 'N4', 'しら（べます）', '', 'investigate; check', '調べます しらべます investigate; check: インターネットで場所を調べてください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (296, '続', 'N4', 'つづ（けます）、つづ（きます）', '', 'continue', '続けます つづけます continue (vt.): 試験の後も、日本語の勉強を続けたいです。 | 続きます つづきます continue (vi.): 会議ぎ は夜まで続きました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (297, '練', 'N4', '', 'レン', 'knead, polish, elaborate', '練習します れんしゅうします practice: カジュアルな会話を練習したいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (298, '落', 'N4', 'お（とします）、お（ちます）', '', 'drop', '落とします おとします drop (vt.): ハンカチを落としましたよ。 | 落ちます おちます fall; drop (vi.): 地震し んで、テレビの上から時計が落ちました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (299, '寝', 'N4', 'ね（ます）', '', 'go to bed; sleep', '寝ます ねます go to bed; sleep: 明日から旅行なので、今日は早く寝ます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (300, '遅', 'N4', 'おそ（い）、おく（れます）', '', 'late', '遅い おそい late: もう遅いですから、帰りましょう。 slow： 私は歩くのが遅いです。 | 遅れます おくれます be late: 今朝、会社に十分遅れてしまいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (301, '顔', 'N4', 'かお', '', 'face', '顔 かお face: その人の顔を忘れてしまいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (302, '首', 'N4', 'くび', '', 'neck', '首 くび neck: あの鳥、首が長いですね。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (303, '声', 'N4', 'こえ', '', 'voice', '声 こえ voice: すみませんが、もっと大きい声で話してください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (304, '都', 'N4', '', 'ト', 'Metropolis', '東京都 とうきょうと the Tokyo metropolitan area: 東京都のホームページを見ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (305, '県', 'N4', '', 'ケン', 'prefecture', '山口県 やまぐちけん Yamaguchi Prefecture: 山口県では、ふぐ（globefish）が有名です。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (306, '区', 'N4', '', 'ク', 'ward', '目黒区 めぐろく Meguro Ward: 私は目黒区に住んでいます。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (307, '市', 'N4', '', 'シ', 'city; municipality', '町田市 まちだし Machida City: 町田市に、大きい図書館があります。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (308, '村', 'N4', 'むら', '', 'village', '村 むら village: ここは村でしたが、去年市に変わりました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (309, '民', 'N4', '', 'ミン', 'people', '市民 しみん citizen: 月に一回、市民が集まって会議ぎ をします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (310, '産', 'N4', '', 'サン', 'product', '生産します せいさんします produce: この会社では、一年間に車を一千万台生産しています。 | 産業 さんぎょう industry: 中国の社会と産業について学びたいです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (311, '林', 'N4', 'はやし', '', 'grove', '林 はやし grove: その小学校は、林の中に建っています。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (312, '森', 'N4', 'もり', '', 'forest', '森 もり forest: 森の中にある小さなホテルに泊と まりました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (313, '池', 'N4', 'いけ', '', 'pond', '池 いけ pond: 公園の池で、子どもとボートに乗りました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (314, '門', 'N4', '', 'モン', 'gate', '門 もん gate: 門を開けたら、大きな犬がいました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (315, '薬', 'N4', 'くすり', '', 'medicine', '薬 くすり medicine: 頭が痛いたかったので、薬を飲んで寝ました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (316, '洗', 'N4', 'あら（います）', 'セン', 'wash', '洗います あらいます wash: 朝起きて、顔を洗って、それから朝ごはんを食べます。 | 洗濯た くします せんたくします wash; launder: 一週間に三回ぐらい洗濯た くします。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (317, '進', 'N4', 'すす（めます）、すす（みます）', '', 'advance; put forward', '進めます すすめます advance; put forward: 時間がないから、早く進めましょう。 | 進みます すすみます advance; go forward: もう少し前に進んでください。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (318, '暗', 'N4', 'くら（い）', '', 'dark', '暗い くらい dark: 空が急に暗くなって、雨が降りそうです。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (319, '光', 'N4', 'ひかり', '', 'light', '光 ひかり light: 月の光が部屋の中に入ってきました。');
INSERT INTO kanjis (kanji_number, kanji, level, kunyomi, onyomi, meaning, examples) VALUES (320, '線', 'N4', '', 'セン', 'line', '線 せん line: あぶ危ないですから、線の外に出ないでください。 | 山手 やまのて線 やまのてせん Yamanote Line: 山手線に乗って、田町駅で降りてください。 49');
